<?= $this->extend('layout') ?><?= $this->section('content') ?><div class="page-heading"><div><p class="eyebrow">LAPORAN / REKAPITULASI</p><h1><?= esc($definition['title']) ?></h1><p class="muted">Laporan dapat dicetak atau diekspor ke CSV.</p></div><div class="heading-actions"><button class="btn btn-secondary" onclick="window.print()" type="button">▣ Cetak</button><a class="btn btn-primary" href="<?= site_url('reports/export/'.$type).'?'.http_build_query($filters+['q'=>$q]) ?>">↓ Ekspor CSV</a></div></div><div class="report-tabs"><?php foreach(['pasien'=>'Data Pasien','dokter'=>'Dokter per Poli','poli'=>'Data Poli','berobat'=>'Transaksi Berobat','biaya'=>'Rekap Biaya'] as $t=>$label): ?><a class="<?= $type===$t?'active':'' ?>" href="<?= site_url('reports/'.$t) ?>"><?= esc($label) ?></a><?php endforeach ?></div><div class="panel report-filter"><div class="panel-heading"><div><h2>Filter Laporan</h2><p>Gunakan tanggal, poli, dokter, pasien, atau kata kunci.</p></div></div><form method="get" action="<?= site_url('reports/'.$type) ?>" class="filter-grid"><div class="field"><label>Tanggal Awal</label><input name="start" type="date" value="<?= esc($filters['start']) ?>" <?= in_array($type,['berobat','biaya'],true)?'':'disabled' ?>></div><div class="field"><label>Tanggal Akhir</label><input name="end" type="date" value="<?= esc($filters['end']) ?>" <?= in_array($type,['berobat','biaya'],true)?'':'disabled' ?>></div><div class="field"><label>Poli</label><select name="poli_id" <?= in_array($type,['berobat','biaya'],true)?'':'disabled' ?>><option value="">Semua Poli</option><?php foreach($poliOptions as $o): ?><option value="<?= esc($o['poli_id']) ?>" <?= $filters['poli_id']===$o['poli_id']?'selected':'' ?>><?= esc($o['nama_poli']) ?></option><?php endforeach ?></select></div><div class="field"><label>Dokter</label><select name="dokter_id" <?= in_array($type,['berobat','biaya'],true)?'':'disabled' ?>><option value="">Semua Dokter</option><?php foreach($dokterOptions as $o): ?><option value="<?= esc($o['dokter_id']) ?>" <?= $filters['dokter_id']===$o['dokter_id']?'selected':'' ?>><?= esc($o['nama_dokter']) ?></option><?php endforeach ?></select></div><div class="field"><label>Pasien</label><select name="pasien_id" <?= in_array($type,['berobat','biaya'],true)?'':'disabled' ?>><option value="">Semua Pasien</option><?php foreach($pasienOptions as $o): ?><option value="<?= esc($o['pasien_id']) ?>" <?= $filters['pasien_id']===$o['pasien_id']?'selected':'' ?>><?= esc($o['nama_pasien']) ?></option><?php endforeach ?></select></div><div class="field field-search"><label>Kata Kunci</label><input type="search" name="q" value="<?= esc($q) ?>" placeholder="Cari nama, ID, keluhan..."></div><div class="filter-actions"><button class="btn btn-primary">Tampilkan</button><a class="btn btn-secondary" href="<?= site_url('reports/'.$type) ?>">Reset</a></div></form></div><div class="report-summary"><div class="summary-card"><div><span>Jumlah Record</span><strong><?= number_format(count($rows)) ?></strong></div></div><?php if(in_array($type,['berobat','biaya'],true)): ?><div class="summary-card"><div><span>Total Biaya Administrasi</span><strong><?= esc('Rp '.number_format($total,0,',','.')) ?></strong></div></div><?php endif ?></div><div class="panel report-table-panel"><div class="panel-heading"><div><h2>Hasil Laporan</h2><p><?= esc(date('d M Y H:i')) ?> · <?= count($rows) ?> record</p></div></div><div class="table-wrap"><table class="data-table report-table"><thead><tr><?php foreach($definition['columns'] as $c): ?><th><?= esc($c[1]) ?></th><?php endforeach ?></tr></thead><tbody><?php if(empty($rows)): ?><tr><td class="empty-state" colspan="<?= count($definition['columns']) ?>">Tidak ada data untuk filter ini.</td></tr><?php else: foreach($rows as $row): ?><tr><?php foreach($definition['columns'] as $c): $v=$row[$c[0]]??''; ?><td><?php if(($c[2]??'')==='currency'): ?><span class="currency"><?= esc('Rp '.number_format((float)$v,0,',','.')) ?></span><?php else: ?><?= esc($v) ?><?php endif ?></td><?php endforeach ?></tr><?php endforeach; endif ?></tbody><?php if(in_array($type,['berobat','biaya'],true)): ?><tfoot><tr><td colspan="<?= count($definition['columns'])-1 ?>">Total Biaya Administrasi</td><td class="currency"><?= esc('Rp '.number_format($total,0,',','.')) ?></td></tr></tfoot><?php endif ?></table></div><div class="list-footer"><?= count($rows) ?> baris ditampilkan</div></div><?= $this->endSection() ?>
